contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        uint before = address(c).balance;
        uint senderBefore = address(this).balance;

        if (before == 0) {
            // ensure at least some ether is sent to c so the property is meaningful
            (bool ok, ) = address(c).call{value: amount}("");
            if (ok) {
                before = address(c).balance;
                senderBefore = address(this).balance;
            }
        }

        bool reverted;
        try c.sudicideAnyone() {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            assert(address(c).balance == 0);
            assert(address(this).balance >= senderBefore + before);
        } else {
            assert(address(c).balance == before);
        }
    }

    receive() external payable {}
}

