contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller) public payable {
        uint256 balanceBefore = address(c).balance;

        // If the caller is not the owner, the call must revert and the balance must remain.
        if (caller != address(this)) {
            bool reverted;
            try c.sudicideAnyone() {
                reverted = false;
            } catch {
                reverted = true;
            }
            assert(reverted && address(c).balance == balanceBefore);
        } else {
            // If the caller is the owner, the call must succeed and c must self-destruct,
            // transferring all its Ether to the caller.
            uint256 callerBalanceBefore = address(this).balance;
            c.sudicideAnyone();
            assert(address(c).balance == 0 && address(this).balance == callerBalanceBefore + balanceBefore);
        }
    }

    receive() external payable {}
}

