contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address newOwner, uint amount) public payable {
        require(address(this).balance >= amount);
        require(newOwner != address(this));

        // Setup: transfer ownership? No setter available. Instead, use the fact that
        // the test contract is the original owner.  To create a non-owner caller, we
        // can simulate by calling from a different address? Not possible without
        // cheatcodes.  So the only observable behaviour is: this contract (owner) can
        // destroy c.  Therefore the rule must be about the owner's call.
        // However, the checker runs run(...) once with msg.sender = InvMutTest, so any
        // call to c.sudicideAnyone() from this test will be from the owner.
        // Therefore the rule: the owner's call succeeds and zeroes c's balance.

        uint256 balBefore = address(c).balance;

        bool reverted;
        try c.sudicideAnyone{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: if the caller is the owner (which is the test contract),
        // the call must not revert and c's balance must become zero.
        // Since the test contract is the owner, we assert that the call succeeds
        // and c's balance is zero afterwards.
        assert(!reverted && address(c).balance == 0);
    }

    receive() external payable {}
}

